ROOT=dict(id='C0660',meaning='法律、规定；依法应尽的义务',core='先有规定，再问是否合规、是否有正当依据、是否守住应尽义务。',image='legal 看规则是否允许，legitimate 看依据是否站得住，loyal 看是否守信并持续支持。',intro='拉丁 lex 是法律，属格 legis 显出 leg-。legal 保留拉丁外形；loyal 经法语音变，意义从守义务转向忠诚。legislator 的后半接“带来、提出”，是把法律带到公共讨论中的人。lex 的更早来源有不同分析，本页不把它与 legere“读、收集”或英语 law 强画成确定的直系关系。',forms='leg- / legis- 是 lex 的词干形式；legalis 经法语形成 loyal，与 legal 同源。legitim- 来自 legitimus。illegal 的 il- 是否定 in- 在 l 前的同化。legislat- 里的 lat- 接 ferre 的 latus“带来”，不是表示侧面的 later-。',branches=[['法律与合规','legal, illegal, legally, legality, illegality, legalize'],['制定法律','legislation, legislator, legislative, legislature, legislate, legific'],['正当依据与身份','legitimate, legitimacy, legitimize, illegitimate, illegitimacy, legitim'],['守信与忠诚','loyal, loyalty, loyally, loyalist, disloyal, disloyalty'],['法律语言与范围','legalese, legalistic, legalism, paralegal, extralegal, nonlegal'],['特别规定与待遇','privilege']],contrasts='legislation 是立法或法律，legislator 是立法者，legislature 是机构。legal 偏合乎法律，legitimate 也问是否有正当理由。illegal 是违法，nonlegal 是与法律无关，extralegal 是法定框架之外。loyal 的忠诚不等于盲从；legalism 也不等于法治。',practice='把三个问题分开：“法律允许吗？”用 legal；“理由站得住吗？”用 legitimate；“是否持续守信支持？”用 loyal。看到 legislation 与 legislate 时，记住真实历史是先有名词，后逆构动词。',words=[],exclude={})
if __name__=='__main__':
    manifest=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text())
    original=next(r for r in manifest['roots'] if r['id']==ROOT['id'])
    ROOT['words']=[w for w in original['family'] if '-' not in w]
    expected=set(ROOT['words'])&set(manifest['owned_words'])
    actual={e['word'] for e in W}
    assert actual==expected,(expected-actual,actual-expected)
    assert len(W)==len(actual)
    assert all(len(e['examples'])>=2 and e['ipa'] and len(e['history'])>=2 for e in W)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'roots_batch200_vid_05.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT/'words_batch200_vid_05.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('leg:',len(W),'new words;',sum(len(e['examples']) for e in W),'bilingual examples')
